# Fuente editable de los 15 campeones de la demo. `python3 tools/build_design.py` genera
# assets/data/champions.json y design/gdd/champion-roster.md a partir de aquí.
# Habilidad: (tecla, nombre, tipo, descripción, cd[5 rangos o 3 para R], coste, daño_base[rangos], ratio(dict), alcance)
def A(k,n,t,d,cd,cost,base,ratio,rng): return dict(key=k,name=n,type=t,desc=d,cooldown=cd,cost=cost,base=base,ratio=ratio,range=rng)

